        venueNord.Rooms.Add(raumNord1);
        venueNord.Rooms.Add(raumNord2);

        var venueSued = new Venue { Name = "Spielstätte Süd" };
        var raumSued = new Room { Name = "Konzertsaal", RowLabels = ["A"], ColumnCount = 4, AisleColumns = [] };
