        db.Venues.AddRange(venueNord, venueSued);
        await db.SaveChangesAsync(ct);

        var spaeteVeranstaltung = new Event
        {
            RoomId = raumNord1.Id,
            Titel = "Spätes Konzert",
            Beschreibung = "...",
            Zeitpunkt = new DateTime(2026, 9, 20, 20, 0, 0),
            DauerMinuten = 90,
            Altersfreigabe = 0,
