        var fruehesEreignis = new Event
        {
            RoomId = raumSued.Id,
            Titel = "Frühe Matinee",
            Beschreibung = "...",
            Zeitpunkt = new DateTime(2026, 9, 10, 11, 0, 0),
            DauerMinuten = 60,
            Altersfreigabe = 0,
