        var bisTagSpaet = NeuesEvent(raum.Id, "Bis-Tag spät", new DateTime(2026, 9, 12, 20, 0, 0));
        var danach = NeuesEvent(raum.Id, "Danach", new DateTime(2026, 9, 13, 0, 0, 0));
        db.Events.AddRange(davor, vonTag, bisTagSpaet, danach);
